import { Motion } from "solid-motionone";

import { cn } from "@/lib/utils";
import {
	type Component,
	Index,
	type JSX,
	type ParentComponent,
	createSignal,
	mergeProps,
	onCleanup,
	onMount,
	splitProps,
} from "solid-js";

interface Sparkle {
	color: string;
	delay: number;
	id: string;
	lifespan: number;
	scale: number;
	x: string;
	y: string;
}

export interface SparklesTextProps extends JSX.HTMLAttributes<HTMLSpanElement> {
	/** The colors of the sparkles */
	colors?: string[];

	/** The class of the text */
	class?: string;

	/** The number of sparkles */
	sparklesCount?: number;
}

export const SparklesText: ParentComponent<SparklesTextProps> = (props) => {
	const [_localProps, forwardProps] = splitProps(props, [
		"children",
		"class",
		"colors",
		"sparklesCount",
	]);
	const localProps = mergeProps(
		{ colors: ["#9E7AFF", "#FE8BBB"], sparklesCount: 10 },
		_localProps,
	);
	const [sparkles, setSparkles] = createSignal<Sparkle[]>([]);

	onMount(() => {
		const generateStar = (): Sparkle => {
			const starX = `${Math.random() * 100}%`;
			const starY = `${Math.random() * 100}%`;
			const color =
				localProps.colors[Math.floor(Math.random() * localProps.colors.length)];
			const delay = Math.random() * 2;
			const scale = Math.random() * 1 + 0.3;
			const lifespan = Math.random() * 10;
			const id = `${starX}-${starY}-${Date.now()}`;

			return { id, x: starX, y: starY, color, delay, scale, lifespan };
		};

		const initializeStars = () => {
			const newSparkles = Array.from(
				{ length: localProps.sparklesCount },
				generateStar,
			);
			setSparkles(newSparkles);
		};

		const updateStars = () => {
			setSparkles((currentSparkles) =>
				currentSparkles.map((star) => {
					if (star.lifespan <= 0) {
						return generateStar();
					}
					return { ...star, lifespan: star.lifespan - 0.1 };
				}),
			);
		};

		initializeStars();
		const interval = setInterval(updateStars, 100);

		onCleanup(() => clearInterval(interval));
	});

	return (
		<span
			class={cn("relative inline-block", localProps.class)}
			{...forwardProps}
		>
			<Index each={sparkles()}>{(sparkle) => <Sparkle {...sparkle()} />}</Index>
			{localProps.children}
		</span>
	);
};

const Sparkle: Component<Sparkle> = (props) => {
	return (
		<Motion.svg
			aria-hidden={true}
			class="pointer-events-none absolute z-20"
			style={{ left: props.x, top: props.y }}
			initial={{ opacity: 0 }}
			animate={{
				opacity: [0, 1, 0],
				scale: [0, props.scale, 0],
				rotate: [75, 120, 150],
			}}
			transition={{
				duration: 1.2,
				repeat: Number.POSITIVE_INFINITY,
				delay: props.delay,
			}}
			width="21"
			height="21"
			viewBox="0 0 21 21"
