			<For each={localProps.text.split("")}>
				{(char, i) => (
					<Motion.div
						initial={localProps.states.initial}
						inView={localProps.states.animate}
						transition={{
							duration: localProps.duration,
							delay: i() * localProps.delayMultiple,
						}}
					>
						{char === " " ? <span>&nbsp;</span> : char}
					</Motion.div>
				)}
			</For>
		</div>
	);
