{"id":"sparkles-text","dependencies":["solid-motionone"],"content":"import { Motion } from "solid-motionone";

import { cn } from "@/lib/utils";
import {
	type Component,
	Index,
	type JSX,
	type ParentComponent,
	createSignal,
	mergeProps,
	onCleanup,
	onMount,
	splitProps,
} from "solid-js";

interface Sparkle {
	color: string;
	delay: number;
	id: string;
	lifespan: number;
	scale: number;
	x: string;
	y: string;
}

export interface SparklesTextProps extends JSX.HTMLAttributes<HTMLSpanElement> {
	/** The colors of the sparkles */
	colors?: string[];

	/** The class of the text */
	class?: string;

	/** The number of sparkles */
	sparklesCount?: number;
}

export const SparklesText: ParentComponent<SparklesTextProps> = (props) => {
	const [_localProps, forwardProps] = splitProps(props, [
		"children",
		"class",
		"colors",
		"sparklesCount",
	]);
	const localProps = mergeProps(
		{ colors: ["#9E7AFF", "#FE8BBB"], sparklesCount: 10 },
		_localProps,
	);
	const [sparkles, setSparkles] = createSignal<Sparkle[]>([]);

	onMount(() => {
		const generateStar = (): Sparkle => {
			const starX = `${Math.random() * 100}%`;
			const starY = `${Math.random() * 100}%`;
			const color =
				localProps.colors[Math.floor(Math.random() * localProps.colors.length)];
			const delay = Math.random() * 2;
			const scale = Math.random() * 1 + 0.3;
			const lifespan = Math.random() * 10;
			const id = `${starX}-${starY}-${Date.now()}`;

			return { id, x: starX, y: starY, color, delay, scale, lifespan };
		};

		const initializeStars = () => {
			const newSparkles = Array.from(
				{ length: localProps.sparklesCount },
				generateStar,
			);
			setSparkles(newSparkles);
		};

		const updateStars = () => {
			setSparkles((currentSparkles) =>
				currentSparkles.map((star) => {
					if (star.lifespan <= 0) {
						return generateStar();
					}
					return { ...star, lifespan: star.lifespan - 0.1 };
				}),
			);
		};

		initializeStars();
		const interval = setInterval(updateStars, 100);

		onCleanup(() => clearInterval(interval));
	});

	return (
		<span
			class={cn("relative inline-block", localProps.class)}
			{...forwardProps}
		>
			<Index each={sparkles()}>{(sparkle) => <Sparkle {...sparkle()} />}</Index>
			{localProps.children}
		</span>
	);
};

const Sparkle: Component<Sparkle> = (props) => {
	return (
		<Motion.svg
			aria-hidden={true}
			class="pointer-events-none absolute z-20"
			style={{ left: props.x, top: props.y }}
			initial={{ opacity: 0 }}
			animate={{
				opacity: [0, 1, 0],
				scale: [0, props.scale, 0],
				rotate: [75, 120, 150],
			}}
			transition={{
				duration: 1.2,
				repeat: Number.POSITIVE_INFINITY,
				delay: props.delay,
			}}
			width="21"
			height="21"
			viewBox="0 0 21 21"
		>
			<path
				d="M9.82531 0.843845C10.0553 0.215178 10.9446 0.215178 11.1746 0.843845L11.8618 2.72026C12.4006 4.19229 12.3916 6.39157 13.5 7.5C14.6084 8.60843 16.8077 8.59935 18.2797 9.13822L20.1561 9.82534C20.7858 10.0553 20.7858 10.9447 20.1561 11.1747L18.2797 11.8618C16.8077 12.4007 14.6084 12.3916 13.5 13.5C12.3916 14.6084 12.4006 16.8077 11.8618 18.2798L11.1746 20.1562C10.9446 20.7858 10.0553 20.7858 9.82531 20.1562L9.13819 18.2798C8.59932 16.8077 8.60843 14.6084 7.5 13.5C6.39157 12.3916 4.19225 12.4007 2.72023 11.8618L0.843814 11.1747C0.215148 10.9447 0.215148 10.0553 0.843814 9.82534L2.72023 9.13822C4.19225 8.59935 6.39157 8.60843 7.5 7.5C8.60843 6.39157 8.59932 4.19229 9.13819 2.72026L9.82531 0.843845Z"
				fill={props.color}
			/>
		</Motion.svg>
	);
};
