{"id":"text-reveal","dependencies":["motion"],"content":"import { cn } from "@/lib/utils";
import { scroll } from "motion";
import {
	type Component,
	For,
	createSignal,
	mergeProps,
	onCleanup,
	onMount,
} from "solid-js";

interface TextRevealByWordProps {
	text: string;
	space?: number;
	class?: string;
}

export const TextReveal: Component<TextRevealByWordProps> = (props) => {
	const localProps = mergeProps({ space: 200 }, props);
	const words = () => localProps.text.split(" ");
	const [scrollY, setScrollY] = createSignal(0);

	let targetRef!: HTMLDivElement;
	onMount(() => {
		const cancel = scroll((progress: number) => setScrollY(progress), {
			target: targetRef,
		});

		onCleanup(() => cancel());
	});

	return (
		<div
			ref={targetRef}
			class={cn("relative", localProps.class)}
			style={{
				height: `calc(100vh + ${words().length * localProps.space}px)`,
			}}
		>
			<div class="sticky top-0 h-screen flex items-center">
				<p class="flex flex-wrap gap-2">
					<For each={words()}>
						{(word, i) => {
							const opacity = () =>
								Math.min(1, Math.max(0.15, scrollY() * words().length - i()));
							return <span style={{ opacity: opacity() }}>{word}&nbsp;</span>;
						}}
					</For>
				</p>
			</div>
		</div>
	);
};
"}

packages/registry/tailwind/typing-animat.content:
{"id":"typing-animation","content":"import {
	type Component,
	createEffect,
	createSignal,
	mergeProps,
	onCleanup,
} from "solid-js";

export interface TypingAnimationProps {
	text: string;
	duration?: number;
}

export const TypingAnimation: Component<TypingAnimationProps> = (props) => {
	const localProps = mergeProps({ duration: 200 }, props);
	const [displayedText, setDisplayedText] = createSignal<string>("");
	const [i, setI] = createSignal<number>(0);

	createEffect(() => {
		const typingEffect = setInterval(() => {
			if (i() < localProps.text.length) {
				setDisplayedText(localProps.text.substring(0, i() + 1));
				setI((i) => i + 1);
			} else {
				clearInterval(typingEffect);
			}
		}, localProps.duration);

		onCleanup(() => {
			clearInterval(typingEffect);
		});
	});

	return <>{displayedText()}</>;
};
"}

